class CmDataRepositoryError(Exception):
    pass


class UnexpectedResponse(CmDataRepositoryError):
    pass


class SoapApiError(CmDataRepositoryError):

    def __init__(self, error_code, cause):
        message = f'SOAP API returned error code: {error_code}. Traceback:\n{cause}'
        super().__init__(message)


class InvalidDictPath(CmDataRepositoryError):
    pass


class PlanNotFound(Exception):
    pass


class ManagedObjectNotFound(Exception):
    pass
